95	const counters = {
96	  guard: 0,
97	  pipe: 0,
98	  interceptor: 0,
99	  handler: 0,
100	};
101	
102	@Injectable()
103	class CountingGuard implements CanActivate {
104	  canActivate() {
105	    counters.guard++;
106	    return true;
107	  }
108	}
109	
110	@Injectable()
111	class CountingPipe implements PipeTransform {
112	  transform(value: unknown) {
113	    counters.pipe++;
114	    return value;
115	  }
116	}
117	
118	@Injectable()
119	class CountingInterceptor implements NestInterceptor {
120	  intercept(_context: ExecutionContext, next: CallHandler): Observable<any> {
121	    counters.interceptor++;
122	    return next.handle();
123	  }
124	}
125	
126	@Controller()
127	class SideEffectController {
128	  @Get('slow')
129	  async slow(@Query('q', CountingPipe) _q?: string) {
130	    counters.handler++;
131	    // Simulate work
132	    await new Promise(resolve => setTimeout(resolve, 500));
133	    return 'ok';
134	  }
135	
136	  @Get('boom')
137	  async boom() {
138	    await new Promise(resolve => setTimeout(resolve, 100));
139	    throw new Error('boom');
140	  }
141	}
